                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        for symbol, bar in available_bars.items():
            self.previous_closes[symbol] = bar.Close

        # No rule evaluation unless every subscribed ticker has today's bar.
        if len(available_bars) != len(self.symbols):
            return

        if self.IsWarmingUp:
            return

        if (not self.spy_sma.IsReady or
                not self.aapl_rsi.IsReady or
                self.previous_spy_sma is None):
            return

        spy_close = available_bars[self.spy].Close
        aapl_close = available_bars[self.aapl].Close

