            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            previous_spy_close = self.previous_closes_before_current(self.spy, data)
            if previous_spy_close is not None:
                crossed_above = (
                    previous_spy_close <= self.previous_spy_sma and
                    spy_close > self.spy_sma.Current.Value
                )
                if crossed_above:
                    shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

    def previous_closes_before_current(self, symbol, data):
        # The current close has already been stored, so retrieve the prior close
        # from the rolling close history kept in the security cache.
        bar = data.Bars[symbol]
        previous = self.Securities[symbol].Cache.GetData[TradeBar]()

        if previous is not None and previous.EndTime < bar.EndTime:
            return previous.Close

        return None
