from AlgorithmImports import *
from collections import deque
import math


class PrivateLotStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=15)

        self.previous_closes = {ticker: None for ticker in self.symbols}
        self.aapl_red_streak = 0

        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_periods = 0
        self.rsi_avg_gain = None
        self.rsi_avg_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        # Continuously update each available market-state series.
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            bar = data.Bars[symbol]
            close = float(bar.Close)

            if ticker == "SPY":
                self.spy_closes.append(close)

            if ticker == "AAPL":
                previous_close = self.previous_closes["AAPL"]

                if previous_close is not None:
                    if close < previous_close:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

                    change = close - previous_close
                    gain = max(change, 0.0)
                    loss = max(-change, 0.0)

                    if self.rsi_periods < 14:
                        self.rsi_gain_sum += gain
                        self.rsi_loss_sum += loss
                        self.rsi_periods += 1

                        if self.rsi_periods == 14:
                            self.rsi_avg_gain = self.rsi_gain_sum / 14.0
                            self.rsi_avg_loss = self.rsi_loss_sum / 14.0
                            self.aapl_rsi = self.CalculateRsi(
                                self.rsi_avg_gain, self.rsi_avg_loss
                            )
                    else:
                        self.rsi_avg_gain = (
                            (self.rsi_avg_gain * 13.0) + gain
                        ) / 14.0
                        self.rsi_avg_loss = (
                            (self.rsi_avg_loss * 13.0) + loss
                        ) / 14.0
                        self.aapl_rsi = self.CalculateRsi(
                            self.rsi_avg_gain, self.rsi_avg_loss
                        )

                self.aapl_closes.append(close)

            self.previous_closes[ticker] = close

        # If any subscribed ticker is missing today, no rules may be evaluated.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Do not trade before every indicator/window used by the rules is formed.
        if len(self.spy_closes) < 101 or self.aapl_rsi is None:
            return

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]
        spy_close = float(data.Bars[spy].Close)
        aapl_close = float(data.Bars[aapl].Close)

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self.SpySmaCross():
            self.MarketOrder(spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi > 60:
            self.MarketOrder(aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self.SpySmaCross():
            shares = int(math.floor(
                (float(self.Portfolio.TotalPortfolioValue) * 0.40) / spy_close
            ))
            if shares > 0:
                self.MarketOrder(spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                shares = int(math.floor(20_000 / aapl_close))
                if shares > 0:
                    self.MarketOrder(aapl, shares)
                    self.strategy_b_shares = shares

    def SpySmaCross(self):
        closes = list(self.spy_closes)
        previous_sma = sum(closes[:100]) / 100.0
        current_sma = sum(closes[1:]) / 100.0
        previous_close = closes[-2]
        current_close = closes[-1]

        return (
            (previous_close < previous_sma and current_close >= current_sma) or
            (previous_close > previous_sma and current_close <= current_sma)
        )

    def CalculateRsi(self, average_gain, average_loss):
        if average_loss == 0:
            return 100.0
        if average_gain == 0:
            return 0.0

        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
